const path = require('path');

const params = $('Normalize User Paths').first().json || {};
const supportedExtensions = ['jpg', 'jpeg', 'png', 'webp'];
const collator = new Intl.Collator('zh-CN', { numeric: true, sensitivity: 'base' });

function normalizeLocalPath(value) {
  let text = value == null ? '' : String(value).trim();
  if ((text.startsWith('"') && text.endsWith('"')) || (text.startsWith("'") && text.endsWith("'"))) {
    text = text.slice(1, -1).trim();
  }
  text = text.replace(/^file:\/\/localhost\//i, '').replace(/^file:\/\//i, '');
  if (/^\/[A-Za-z]:\//.test(text)) text = text.slice(1);
  return text.replace(/\\/g, '/').replace(/\/+/g, '/').replace(/\/+$/, '');
}

function joinPath(...parts) {
  return parts
    .filter((part) => part != null && String(part).trim() !== '')
    .map((part, index) => {
      let text = normalizeLocalPath(part);
      if (index > 0) text = text.replace(/^\/+/, '');
      return text.replace(/\/+$/, '');
    })
    .join('/');
}

function pathLeaf(value) {
  const normalized = normalizeLocalPath(value);
  const parts = normalized.split('/').filter(Boolean);
  return parts[parts.length - 1] || '';
}

function relativeFromRoot(root, absolutePath, label) {
  const absoluteRoot = path.resolve(root);
  const resolved = path.resolve(absolutePath);
  const relative = path.relative(absoluteRoot, resolved);
  if (!relative || relative === '..' || relative.startsWith('..' + path.sep) || path.isAbsolute(relative)) {
    throw new Error(label + ' 超出来源目录：' + absolutePath);
  }
  return relative.split(path.sep).join('/');
}

function extractImageNumbers(baseName, index) {
  const groupMatch = baseName.match(/__(\d+)(?=-|$)/)
    || baseName.match(/^第(\d+)组(?:-|_|$)/)
    || baseName.match(/^(\d+)(?=-|_|$)/);
  const subMatch = baseName.match(/-(\d+)$/);
  const groupNumber = groupMatch ? Number(groupMatch[1]) : index + 1;
  const subNumber = subMatch ? Number(subMatch[1]) : index + 1;
  return {
    outputNumber: String(groupNumber).padStart(2, '0'),
    outputSubNumber: String(subNumber).padStart(2, '0'),
  };
}

const sourceFolderDir = normalizeLocalPath(params.sourceFolderDir || params.folderPath || '');
if (!sourceFolderDir) throw new Error('sourceFolderDir is required.');
const rawItems = $input.all().map((item, originalIndex) => {
  const binary = item.binary && item.binary.data ? item.binary.data : {};
  const sourceDirectory = normalizeLocalPath(binary.directory || item.json.sourceDirectory || sourceFolderDir);
  const sourceFileName = String(binary.fileName || item.json.fileName || '');
  if (!sourceFileName) throw new Error('读取到的第 ' + originalIndex + ' 个图片缺少 fileName。');
  const absolutePath = path.resolve(sourceDirectory, sourceFileName);
  const sourceRelativePath = relativeFromRoot(sourceFolderDir, absolutePath, '读取图片');
  const sourceExtension = String(binary.fileExtension || item.json.fileExtension || sourceFileName.split('.').pop() || '').toLowerCase();
  if (!supportedExtensions.includes(sourceExtension)) throw new Error('读取到不支持的图片类型：' + sourceRelativePath);
  return { item, originalIndex, sourceDirectory, sourceFileName, sourceRelativePath, sourceExtension };
});

const actualByRelativePath = new Map();
for (const entry of rawItems) {
  if (actualByRelativePath.has(entry.sourceRelativePath)) throw new Error('读取结果包含重复图片：' + entry.sourceRelativePath);
  actualByRelativePath.set(entry.sourceRelativePath, entry);
}

const manifestFiles = Array.isArray(params.orderedSelectedFiles) ? params.orderedSelectedFiles : null;
let orderedItems;
if (manifestFiles) {
  if (manifestFiles.length !== rawItems.length) {
    throw new Error('读取到的图片数量与 selection-manifest.json 不一致：manifest=' + manifestFiles.length + '，实际=' + rawItems.length + '。');
  }
  orderedItems = manifestFiles.map((manifestEntry, index) => {
    if (!manifestEntry || manifestEntry.sortOrder !== index) throw new Error('Normalize User Paths 输出的 sortOrder 不连续。');
    const relativePath = String(manifestEntry.targetRelativePath || '');
    const actual = actualByRelativePath.get(relativePath);
    if (!actual) throw new Error('selection-manifest.json 中的图片未被读取：' + relativePath);
    return { ...actual, manifestEntry };
  });
  const manifestTargets = new Set(manifestFiles.map((entry) => String(entry.targetRelativePath || '')));
  const extras = rawItems.filter((entry) => !manifestTargets.has(entry.sourceRelativePath));
  if (extras.length) throw new Error('来源目录包含 manifest 未登记图片：' + extras.map((entry) => entry.sourceRelativePath).join(', '));
} else {
  orderedItems = [...rawItems]
    .sort((left, right) => collator.compare(left.sourceRelativePath, right.sourceRelativePath))
    .map((entry) => ({ ...entry, manifestEntry: null }));
}

const outputNames = new Set();
return orderedItems.map((entry, index) => {
  const { item, originalIndex, sourceDirectory, sourceFileName, sourceRelativePath, sourceExtension, manifestEntry } = entry;
  const baseName = sourceFileName.replace(/\.[^.]+$/, '');
  const { outputNumber, outputSubNumber } = extractImageNumbers(baseName, index);
  const outputFileName = outputNumber + '-' + outputSubNumber + '.png';
  if (outputNames.has(outputFileName)) {
    throw new Error('按现有命名规则生成了重复输出文件名：' + outputFileName + '；为避免覆盖，本次已停止。');
  }
  outputNames.add(outputFileName);

  const outputSubDir = normalizeLocalPath(params.defaultOutputSubDir || '');
  if (!outputSubDir) throw new Error('defaultOutputSubDir is required.');
  const outputPath = joinPath(outputSubDir, outputFileName);
  return {
    json: {
      ...item.json,
      sourceDirectory,
      sourceDirectoryName: pathLeaf(sourceDirectory) || params.sourceFolderName || 'output',
      sourceFileName,
      sourceRelativePath,
      sourceOriginalRelativePath: manifestEntry && manifestEntry.sourceRelativePath ? manifestEntry.sourceRelativePath : sourceRelativePath,
      sourceExtension,
      baseName,
      shouldProcess: true,
      sortOrder: index,
      mediaOrderSource: params.mediaOrderSource || 'filename-natural-legacy',
      outputParentDir: params.outputParentDir,
      SKU: params.SKU,
      productName: params.productName,
      variants: params.variants,
      n8nExecutionId: params.n8nExecutionId,
      variantId: params.variantId,
      sourceSubmissionId: params.sourceSubmissionId,
      sourceManifestTaskId: params.sourceManifestTaskId,
      sourceManifestStageId: params.sourceManifestStageId,
      outputTimestamp: params.outputTimestamp,
      outputNumber,
      outputSubNumber,
      outputFileName,
      outputSubDir,
      outputPath,
    },
    binary: item.binary,
    pairedItem: { item: originalIndex },
  };
});

const fs = require('fs');
const path = require('path');

const imageExtensions = ['jpg', 'jpeg', 'png', 'webp'];
const imageGlob = '**/*.{jpg,jpeg,png,webp,JPG,JPEG,PNG,WEBP}';

function cleanInput(value) {
  let text = value == null ? '' : String(value).trim();
  if ((text.startsWith('"') && text.endsWith('"')) || (text.startsWith("'") && text.endsWith("'"))) {
    text = text.slice(1, -1).trim();
  }
  return text;
}

function safeDecode(value) {
  try {
    return decodeURIComponent(value);
  } catch (error) {
    return value;
  }
}

function normalizeFileUrl(value) {
  const match = value.match(/^file:\/\/(.*)$/i);
  if (!match) return value;
  let filePath = safeDecode(match[1]);
  filePath = filePath.replace(/^localhost\//i, '');
  if (/^\/[A-Za-z]:\//.test(filePath)) filePath = filePath.slice(1);
  return filePath;
}

function normalizeLocalPath(value, { keepTrailingSlash = false } = {}) {
  let text = cleanInput(value);
  text = normalizeFileUrl(text);
  text = safeDecode(text);
  text = text.replace(/\\/g, '/').replace(/\/+/g, '/');
  if (!keepTrailingSlash) text = text.replace(/\/+$/, '');
  return text;
}

function joinPath(...parts) {
  return parts
    .filter((part) => part != null && String(part).trim() !== '')
    .map((part, index) => {
      let text = normalizeLocalPath(part);
      if (index > 0) text = text.replace(/^\/+/, '');
      return text.replace(/\/+$/, '');
    })
    .join('/');
}

function pathLeaf(value) {
  const normalized = normalizeLocalPath(value);
  if (!normalized) return '';
  const parts = normalized.split('/').filter(Boolean);
  return parts[parts.length - 1] || '';
}

function cleanPathPart(value) {
  return String(value || '').trim().replace(/[<>:"/\\|?*\x00-\x1F]/g, '_').replace(/[. ]+$/g, '');
}

function timestampForFolderName() {
  const now = new Date();
  const pad = (number, length = 2) => String(number).padStart(length, '0');
  return [now.getFullYear(), pad(now.getMonth() + 1), pad(now.getDate())].join('')
    + '-'
    + [pad(now.getHours()), pad(now.getMinutes()), pad(now.getSeconds())].join('')
    + '-'
    + pad(now.getMilliseconds(), 3);
}

function isHttpUrl(value) {
  return /^https?:\/\//i.test(value);
}

function isImageFilePath(value) {
  const clean = value.split(/[?#]/)[0];
  const ext = clean.includes('.') ? clean.split('.').pop().toLowerCase() : '';
  return imageExtensions.includes(ext);
}

function normalizeRelativePath(value, label) {
  const normalized = normalizeLocalPath(value).replace(/^\.\/+/, '');
  if (!normalized || normalized.startsWith('/') || /^[A-Za-z]:\//.test(normalized)) {
    throw new Error(label + ' 必须是非空相对路径。');
  }
  const segments = normalized.split('/');
  if (segments.some((segment) => !segment || segment === '.' || segment === '..')) {
    throw new Error(label + ' 包含不安全的路径片段：' + normalized);
  }
  return segments.join('/');
}

function resolveInside(root, relativePath, label) {
  const absoluteRoot = path.resolve(root);
  const absoluteTarget = path.resolve(absoluteRoot, ...relativePath.split('/'));
  const relative = path.relative(absoluteRoot, absoluteTarget);
  if (!relative || relative === '..' || relative.startsWith('..' + path.sep) || path.isAbsolute(relative)) {
    throw new Error(label + ' 超出来源目录：' + relativePath);
  }
  return absoluteTarget;
}

function readJsonIfExists(filePath, label) {
  if (!fs.existsSync(filePath)) return null;
  try {
    const parsed = JSON.parse(fs.readFileSync(filePath, 'utf8'));
    if (!parsed || typeof parsed !== 'object' || Array.isArray(parsed)) throw new Error('根节点必须是对象');
    return parsed;
  } catch (error) {
    throw new Error('读取 ' + label + ' 失败：' + (error && error.message ? error.message : String(error)));
  }
}

function orderManifestFiles(manifest) {
  if (!manifest || !Array.isArray(manifest.selectedFiles) || manifest.selectedFiles.length === 0) {
    throw new Error('selection-manifest.json 的 selectedFiles 必须是非空数组。');
  }
  const files = manifest.selectedFiles.map((entry, index) => {
    if (!entry || typeof entry !== 'object' || Array.isArray(entry)) {
      throw new Error('selection-manifest.json 的 selectedFiles[' + index + '] 无效。');
    }
    return { ...entry };
  });
  const hasSortOrder = files.map((entry) => Object.prototype.hasOwnProperty.call(entry, 'sortOrder'));
  const anySortOrder = hasSortOrder.some(Boolean);
  const allSortOrder = hasSortOrder.every(Boolean);
  if (anySortOrder && !allSortOrder) throw new Error('selection-manifest.json 的 sortOrder 不得部分缺失。');
  if (!allSortOrder) return { files, orderSource: 'selection-manifest-array' };

  const seen = new Set();
  for (const [index, entry] of files.entries()) {
    if (!Number.isInteger(entry.sortOrder) || entry.sortOrder < 0) {
      throw new Error('selection-manifest.json 的 selectedFiles[' + index + '].sortOrder 必须是非负整数。');
    }
    if (seen.has(entry.sortOrder)) throw new Error('selection-manifest.json 的 sortOrder 重复：' + entry.sortOrder);
    seen.add(entry.sortOrder);
  }
  const ordered = [...files].sort((left, right) => left.sortOrder - right.sortOrder);
  ordered.forEach((entry, index) => {
    if (entry.sortOrder !== index) throw new Error('selection-manifest.json 的 sortOrder 必须从 0 连续递增。');
  });
  return { files: ordered, orderSource: 'selection-manifest-sortOrder' };
}

return $input.all().map((item, index) => {
  const input = item.json || {};
  const folderPath = normalizeLocalPath(input.folderPath || input.path || input.sourcePath || input.filePath || '');
  const outputParentDir = normalizeLocalPath(input.outputParentDir || '');
  if (typeof input.SKU !== 'string') throw new Error('n8n_setParameter_xxx.json 的 SKU 必须是 String。');
  if (typeof input.productName !== 'string') throw new Error('n8n_setParameter_xxx.json 的 productName 必须是 String。');
  if (typeof input.variants !== 'string') throw new Error('n8n_setParameter_xxx.json 的 variants 必须是 String。');
  const SKU = input.SKU.trim();
  const productName = input.productName.trim();
  const variants = input.variants.trim();
  const executionId = String($execution.id || '').trim();
  if (!/^\d{7}$/.test(SKU)) throw new Error('n8n_setParameter_xxx.json 的 SKU 必须是保留前导零的 7 位数字。');
  if (!productName) throw new Error('n8n_setParameter_xxx.json 的 productName 不能为空。');
  if (!variants) throw new Error('n8n_setParameter_xxx.json 的 variants 不能为空。');
  if (!/^\d+$/.test(executionId)) throw new Error('当前工作流 executionId 无效。');
  const safeProductName = cleanPathPart(productName);
  if (!safeProductName) throw new Error('n8n_setParameter_xxx.json 的 productName 清理后为空。');

  const logoRaw = cleanInput(input.logo || input.logoPath || input.logoUrl || '');
  const logoIsRemote = isHttpUrl(logoRaw);
  const logoNormalized = logoIsRemote ? safeDecode(logoRaw) : normalizeLocalPath(logoRaw);
  if (!folderPath) throw new Error('folderPath is empty after normalization');
  if (isHttpUrl(folderPath)) throw new Error('Source image only supports local path or file:// URL, not HTTP URL');
  if (!outputParentDir) throw new Error('outputParentDir is empty after normalization');
  if (isHttpUrl(outputParentDir)) throw new Error('outputParentDir only supports local path or file:// URL, not HTTP URL');
  if (!logoNormalized) throw new Error('logo path/url is empty after normalization');

  const sourceInputType = isImageFilePath(folderPath) ? 'file' : 'folder';
  const sourceSelector = sourceInputType === 'file' ? folderPath : joinPath(folderPath, imageGlob);
  const sourceFolderDir = sourceInputType === 'file' ? normalizeLocalPath(path.dirname(folderPath)) : folderPath;
  const sourceFolderName = pathLeaf(sourceFolderDir) || 'output';
  const outputTimestamp = input.outputTimestamp || timestampForFolderName();
  const defaultOutputSubDir = joinPath(outputParentDir, SKU + '-' + safeProductName + '-' + executionId);
  const logoInputType = logoIsRemote ? 'httpUrl' : 'localFile';

  const selectionManifestPath = path.join(sourceFolderDir, 'selection-manifest.json');
  const taskContextPath = path.join(sourceFolderDir, 'task-context.json');
  const handoffPath = path.join(sourceFolderDir, 'handoff.json');
  const selectionManifest = sourceInputType === 'folder' ? readJsonIfExists(selectionManifestPath, 'selection-manifest.json') : null;
  const sourceTaskContext = sourceInputType === 'folder' ? readJsonIfExists(taskContextPath, 'task-context.json') : null;
  const sourceHandoff = sourceInputType === 'folder' ? readJsonIfExists(handoffPath, 'handoff.json') : null;

  let orderedSelectedFiles = null;
  let mediaOrderSource = 'filename-natural-legacy';
  if (selectionManifest) {
    const ordered = orderManifestFiles(selectionManifest);
    const seenTargets = new Set();
    orderedSelectedFiles = ordered.files.map((entry, orderIndex) => {
      const targetRelativePath = normalizeRelativePath(entry.targetRelativePath, 'selectedFiles[' + orderIndex + '].targetRelativePath');
      const extension = targetRelativePath.includes('.') ? targetRelativePath.split('.').pop().toLowerCase() : '';
      if (!imageExtensions.includes(extension)) throw new Error('manifest 包含不支持的图片类型：' + targetRelativePath);
      if (seenTargets.has(targetRelativePath)) throw new Error('manifest 包含重复的 targetRelativePath：' + targetRelativePath);
      seenTargets.add(targetRelativePath);
      const absolutePath = resolveInside(sourceFolderDir, targetRelativePath, 'selectedFiles[' + orderIndex + '].targetRelativePath');
      let stat;
      try {
        stat = fs.statSync(absolutePath);
      } catch (error) {
        throw new Error('manifest 图片不存在：' + targetRelativePath);
      }
      if (!stat.isFile() || stat.size <= 0) throw new Error('manifest 图片不是有效的非空文件：' + targetRelativePath);
      return {
        sortOrder: orderIndex,
        targetRelativePath,
        sourceRelativePath: entry.sourceRelativePath == null ? null : normalizeRelativePath(entry.sourceRelativePath, 'selectedFiles[' + orderIndex + '].sourceRelativePath'),
      };
    });
    mediaOrderSource = ordered.orderSource;
  }

  const sourceSubmissionId = String(
    input.sourceSubmissionId
    || (sourceTaskContext && sourceTaskContext.sourceSubmissionId)
    || (sourceHandoff && sourceHandoff.submissionId)
    || '',
  ).trim();

  return {
    json: {
      ...input,
      folderPath,
      SKU,
      productName,
      variants,
      n8nExecutionId: executionId,
      sourceSelector,
      sourceInputType,
      sourceFolderDir,
      sourceFolderName,
      outputParentDir,
      outputTimestamp,
      defaultOutputSubDir,
      logoNormalized,
      logoInputType,
      logoIsRemote,
      sourceSubmissionId,
      sourceManifestTaskId: selectionManifest && selectionManifest.taskId ? String(selectionManifest.taskId) : '',
      sourceManifestStageId: selectionManifest && selectionManifest.sourceStageId ? String(selectionManifest.sourceStageId) : '',
      selectionManifestPath: selectionManifest ? normalizeLocalPath(selectionManifestPath) : '',
      orderedSelectedFiles,
      mediaOrderSource,
    },
    binary: item.binary,
    pairedItem: item.pairedItem ?? { item: index },
  };
});

const fs = require('fs');
const path = require('path');

const items = $input.all();
if (items.length === 0) {
  throw new Error('Create Output Directory: no input items received.');
}

const first = items[0].json || {};
const outputSubDir = String(first.outputSubDir || '').trim();
const SKU = typeof first.SKU === 'string' ? first.SKU.trim() : '';
const productName = typeof first.productName === 'string' ? first.productName.trim() : '';
const variants = typeof first.variants === 'string' ? first.variants.trim() : '';
const n8nExecutionId = String(first.n8nExecutionId || $execution.id || '').trim();

if (!outputSubDir) {
  throw new Error('Create Output Directory: outputSubDir is empty.');
}
if (!/^\d{7}$/.test(SKU)) {
  throw new Error('Create Output Directory: SKU must be a 7-digit String.');
}
if (!productName) {
  throw new Error('Create Output Directory: productName must be a non-empty String.');
}
if (!variants) {
  throw new Error('Create Output Directory: variants must be a non-empty String.');
}
if (!/^\d+$/.test(n8nExecutionId)) {
  throw new Error('Create Output Directory: n8nExecutionId must be numeric.');
}

for (let index = 0; index < items.length; index += 1) {
  const json = items[index].json || {};
  if (String(json.outputSubDir || '').trim() !== outputSubDir) {
    throw new Error(`Create Output Directory: item ${index} has a different outputSubDir.`);
  }
  if (String(json.SKU || '').trim() !== SKU) {
    throw new Error(`Create Output Directory: item ${index} has a different SKU.`);
  }
  if (String(json.productName || '').trim() !== productName) {
    throw new Error(`Create Output Directory: item ${index} has a different productName.`);
  }
  if (String(json.variants || '').trim() !== variants) {
    throw new Error(`Create Output Directory: item ${index} has different variants.`);
  }
}

const taskContext = {
  schemaVersion: 1,
  workflowCode: 'E005',
  SKU,
  productName,
  variants,
  ...(first.variantId ? { variantId: String(first.variantId) } : {}),
  ...(first.sourceSubmissionId ? { sourceSubmissionId: String(first.sourceSubmissionId) } : {}),
  n8nExecutionId,
};

const target = path.join(outputSubDir, 'task-context.json');

try {
  fs.mkdirSync(outputSubDir, { recursive: true });
  fs.writeFileSync(target, JSON.stringify(taskContext, null, 2), 'utf8');

  const saved = JSON.parse(fs.readFileSync(target, 'utf8'));
  if (
    saved.SKU !== taskContext.SKU
    || saved.productName !== taskContext.productName
    || saved.variants !== taskContext.variants
    || saved.n8nExecutionId !== taskContext.n8nExecutionId
  ) {
    throw new Error('task-context verification failed.');
  }
} catch (error) {
  const code = error && error.code ? ` [${error.code}]` : '';
  const message = error && error.message ? error.message : String(error);
  throw new Error(`Create Output Directory failed${code}: ${message}`);
}

return [{
  json: {
    ok: true,
    outputSubDir,
    target,
    taskContext,
  },
}];

const fs = require('fs');
const path = require('path');

function normalizeLocalPath(value) {
  return String(value == null ? '' : value).trim().replace(/\\/g, '/').replace(/\/+/g, '/').replace(/\/+$/, '');
}

function stableOrderProjection(manifest) {
  return (Array.isArray(manifest && manifest.selectedFiles) ? manifest.selectedFiles : []).map((entry) => ({
    sortOrder: entry.sortOrder,
    sourceRelativePath: entry.sourceRelativePath,
    targetRelativePath: entry.targetRelativePath,
  }));
}

const items = $input.all();
if (items.length === 0) throw new Error('Finalize Ordered Output Manifest: no output images received.');
const ordered = [...items].sort((left, right) => Number(left.json.sortOrder) - Number(right.json.sortOrder));
ordered.forEach((item, index) => {
  if (!Number.isInteger(item.json.sortOrder) || item.json.sortOrder !== index) {
    throw new Error('Finalize Ordered Output Manifest: sortOrder must be unique, contiguous, and start at 0.');
  }
});

const first = ordered[0].json || {};
const outputSubDir = normalizeLocalPath(first.outputSubDir || '');
if (!outputSubDir) throw new Error('Finalize Ordered Output Manifest: outputSubDir is empty.');
const selectedFiles = [];
const seenOutputNames = new Set();
for (const [index, item] of ordered.entries()) {
  const json = item.json || {};
  if (normalizeLocalPath(json.outputSubDir || '') !== outputSubDir) {
    throw new Error('Finalize Ordered Output Manifest: item ' + index + ' has a different outputSubDir.');
  }
  const outputFileName = String(json.outputFileName || '').trim();
  if (!outputFileName || outputFileName.includes('/') || outputFileName.includes('\\')) {
    throw new Error('Finalize Ordered Output Manifest: item ' + index + ' has an invalid outputFileName.');
  }
  if (seenOutputNames.has(outputFileName)) throw new Error('Finalize Ordered Output Manifest: duplicate output file ' + outputFileName + '.');
  seenOutputNames.add(outputFileName);
  const outputPath = path.resolve(String(json.outputPath || path.join(outputSubDir, outputFileName)));
  const relativeOutputPath = path.relative(path.resolve(outputSubDir), outputPath);
  if (!relativeOutputPath || relativeOutputPath === '..' || relativeOutputPath.startsWith('..' + path.sep) || path.isAbsolute(relativeOutputPath)) {
    throw new Error('Finalize Ordered Output Manifest: output path escapes outputSubDir: ' + outputFileName);
  }
  let stat;
  try {
    stat = fs.statSync(outputPath);
  } catch (error) {
    throw new Error('Finalize Ordered Output Manifest: output image is missing: ' + outputFileName);
  }
  if (!stat.isFile() || stat.size <= 0) throw new Error('Finalize Ordered Output Manifest: output image is empty or invalid: ' + outputFileName);
  selectedFiles.push({
    sortOrder: index,
    sourceRelativePath: String(json.sourceOriginalRelativePath || json.sourceRelativePath || json.sourceFileName || ''),
    targetRelativePath: outputFileName,
    fileName: outputFileName,
    sizeBytes: stat.size,
    lastModifiedAt: stat.mtime.toISOString(),
  });
}

const sourceSubmissionId = String(first.sourceSubmissionId || '').trim();
const taskContextPath = path.join(outputSubDir, 'task-context.json');
let taskContext;
try {
  taskContext = JSON.parse(fs.readFileSync(taskContextPath, 'utf8'));
} catch (error) {
  throw new Error('Finalize Ordered Output Manifest: cannot read task-context.json: ' + (error && error.message ? error.message : String(error)));
}
if (sourceSubmissionId && String(taskContext.sourceSubmissionId || '') !== sourceSubmissionId) {
  throw new Error('Finalize Ordered Output Manifest: task-context.json did not retain sourceSubmissionId.');
}

const manifest = {
  schemaVersion: '1.0',
  taskId: String(first.sourceManifestTaskId || ''),
  sourceStageId: String(first.sourceManifestStageId || 'E003'),
  targetStageId: 'E005',
  packageMode: 'flatten',
  sourceFolderName: String(first.sourceDirectoryName || ''),
  sourceSubmissionId,
  selectedImageCount: selectedFiles.length,
  selectedFiles,
  imageOrderSource: String(first.mediaOrderSource || 'filename-natural-legacy'),
  productSku: String(first.SKU || ''),
  productName: String(first.productName || ''),
  variantId: first.variantId == null ? null : String(first.variantId),
  variantName: String(first.variants || ''),
  n8nExecutionId: String(first.n8nExecutionId || $execution.id || ''),
  createdAt: new Date().toISOString(),
};

const target = path.join(outputSubDir, 'selection-manifest.json');
if (fs.existsSync(target)) {
  let existing;
  try {
    existing = JSON.parse(fs.readFileSync(target, 'utf8'));
  } catch (error) {
    throw new Error('Finalize Ordered Output Manifest: existing selection-manifest.json is invalid.');
  }
  if (JSON.stringify(stableOrderProjection(existing)) !== JSON.stringify(stableOrderProjection(manifest))) {
    throw new Error('Finalize Ordered Output Manifest: existing manifest has a different ordered selection; refusing to overwrite it.');
  }
} else {
  const temporary = target + '.__tmp__' + String($execution.id || Date.now());
  try {
    fs.writeFileSync(temporary, JSON.stringify(manifest, null, 2), 'utf8');
    const readback = JSON.parse(fs.readFileSync(temporary, 'utf8'));
    if (JSON.stringify(stableOrderProjection(readback)) !== JSON.stringify(stableOrderProjection(manifest))) {
      throw new Error('temporary manifest readback verification failed.');
    }
    fs.renameSync(temporary, target);
  } finally {
    if (fs.existsSync(temporary)) fs.unlinkSync(temporary);
  }
}

const saved = JSON.parse(fs.readFileSync(target, 'utf8'));
if (JSON.stringify(stableOrderProjection(saved)) !== JSON.stringify(stableOrderProjection(manifest))) {
  throw new Error('Finalize Ordered Output Manifest: final readback verification failed.');
}

return [{
  json: {
    ok: true,
    outputSubDir,
    selectionManifestPath: normalizeLocalPath(target),
    sourceSubmissionId,
    selectedImageCount: selectedFiles.length,
    selectedFiles,
  },
}];
